import React from 'react';

const CARD_TYPES = [
  { type: 'bar', label: 'Bar Chart', icon: '📊' },
  { type: 'line', label: 'Line Chart', icon: '📈' },
  { type: 'pie', label: 'Pie Chart', icon: '🥧' },
  { type: 'scalar', label: 'Metric', icon: '🔢' },
  { type: 'table', label: 'Table', icon: '📋' },
  { type: 'map', label: 'Map', icon: '🗺️' },
];

export default function CardPalette({ onAdd }) {
  return (
    <div style={styles.palette}>
      <h3 style={styles.title}>Card Types</h3>
      {CARD_TYPES.map(ct => (
        <div
          key={ct.type}
          style={styles.item}
          draggable
          onDragStart={e => e.dataTransfer.setData('cardType', ct.type)}
          onClick={() => onAdd({ type: ct.type, title: ct.label })}
        >
          <span style={styles.icon}>{ct.icon}</span>
          <span>{ct.label}</span>
        </div>
      ))}
    </div>
  );
}

const styles = {
  palette: { width: 180, background: '#f8f9fa', borderRight: '1px solid #dee2e6', padding: 16, flexShrink: 0 },
  title: { fontSize: 13, fontWeight: 700, color: '#495057', marginBottom: 12, textTransform: 'uppercase', letterSpacing: 1 },
  item: {
    display: 'flex', alignItems: 'center', gap: 8, padding: '8px 10px',
    marginBottom: 6, background: '#fff', border: '1px solid #dee2e6',
    borderRadius: 6, cursor: 'grab', fontSize: 13,
    userSelect: 'none',
  },
  icon: { fontSize: 16 },
};
